import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.TQKaXlFR.js";const m=JSON.parse('{"title":"阅读路径","description":"","frontmatter":{},"headers":[],"relativePath":"overview/reading-path.md","filePath":"overview/reading-path.md"}'),i={name:"overview/reading-path.md"};function h(d,e,l,n,s,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="阅读路径" tabindex="-1">阅读路径 <a class="header-anchor" href="#阅读路径" aria-label="Permalink to &quot;阅读路径&quot;">​</a></h1><h2 id="用途与前置" tabindex="-1">用途与前置 <a class="header-anchor" href="#用途与前置" aria-label="Permalink to &quot;用途与前置&quot;">​</a></h2><p>根据你在项目中的身份，选择一条能得到具体结果的路径。本页适合首次接手者，也适合从应用“当前页面帮助”进入但不知道下一步读什么的用户。阅读不要求登录；执行管理操作、配置密钥、调用 API 时仍遵守对应页面权限和环境要求。</p><h2 id="只想体验和阅读" tabindex="-1">只想体验和阅读 <a class="header-anchor" href="#只想体验和阅读" aria-label="Permalink to &quot;只想体验和阅读&quot;">​</a></h2><p>可从<a href="https://beidaomitu233.github.io/xinghui-admin-vue3/" target="_blank" rel="noreferrer">Pages 后台演示目标</a>和<a href="https://beidaomitu233.github.io/xinghui-admin-vue3/docs/" target="_blank" rel="noreferrer">Pages 文档目标</a>开始，实际发布状态看<a href="https://github.com/beidaomitu233/xinghui-admin-vue3/actions" target="_blank" rel="noreferrer">公开仓库 Actions</a>。静态演示的本地数据与模拟结果不验证真实接口、数据库或供应商；需要接入真实应用时再走下面的安装、权限和部署路径。</p><h2 id="管理人员-先完成一条操作链" tabindex="-1">管理人员：先完成一条操作链 <a class="header-anchor" href="#管理人员-先完成一条操作链" aria-label="Permalink to &quot;管理人员：先完成一条操作链&quot;">​</a></h2><ol><li>阅读<a href="./../features/accounts.html">账号与用户</a>，确认当前账号角色和操作权限。</li><li>在<a href="./../features/menus.html">三个菜单组</a>中找到功能；按需要阅读<a href="./../features/dictionary.html">字典管理</a>、<a href="./../features/parameters.html">系统参数</a>或<a href="./../features/news.html">资讯</a>。</li><li>管理业务配置前，核对<a href="./../features/business-config.html">业务配置</a>的平台身份及敏感值不回显规则。</li><li>阅读<a href="./../features/bulk.html">导入导出</a>再上传用户表格；角色字段和新账号激活步骤不能跳过。</li></ol><p>正常结果是完成一次查询、保存和刷新核对，而不是只看到成功提示。若菜单不存在，检查授权；若保存报冲突，重新读取当前 revision 后再操作。不要重置密码、重复发送短信或重复调用模型来验证无关页面。</p><h2 id="普通业务使用者-个人入口与授权业务" tabindex="-1">普通业务使用者：个人入口与授权业务 <a class="header-anchor" href="#普通业务使用者-个人入口与授权业务" aria-label="Permalink to &quot;普通业务使用者：个人入口与授权业务&quot;">​</a></h2><p>从<a href="./../features/notifications.html">个人通知</a>了解未读、详情和已读操作。仅有本人通知的账号会看到只含个人收件箱的通用组；这不授予通知模板、业务配置或模型管理权限。</p><p>如需要填写表单，先取得<a href="./../features/lowcode.html">低代码表单</a>说明的发布表单与记录权限，再打开填写地址。正常结果是能提交当前发布版本并在获权记录页面读取；没有发布、没有记录操作码或不在数据范围内时应联系管理员，而不是寻找匿名入口。</p><h2 id="开发者-从现有模块理解契约" tabindex="-1">开发者：从现有模块理解契约 <a class="header-anchor" href="#开发者-从现有模块理解契约" aria-label="Permalink to &quot;开发者：从现有模块理解契约&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>要读什么</th><th>可核对的成果</th></tr></thead><tbody><tr><td>1</td><td><a href="./../guide/quickstart.html">快速开始</a>、<a href="./../guide/configuration.html">运行配置</a>、<a href="./../guide/verification.html">运行验证</a></td><td>在自己的环境启动并完成最小验证</td></tr><tr><td>2</td><td><a href="./../development/structure.html">结构</a>、<a href="./../development/routes-permissions.html">路由权限</a></td><td>找到页面、API、服务和操作码的实际位置</td></tr><tr><td>3</td><td><a href="./../reference/api-conventions.html">API约定</a>、<a href="./../reference/error-codes.html">错误码</a></td><td>正确处理HTTP/业务码、数字串ID和冲突</td></tr><tr><td>4</td><td><a href="./../components/paged-list.html">分页</a>、<a href="./../components/edit-detail.html">编辑详情</a>、<a href="./../components/feedback.html">反馈</a></td><td>复用当前组件的真实参数、事件和失败状态</td></tr><tr><td>5</td><td><a href="./../development/module-extension.html">新增模块</a>、<a href="./../reference/database-migrations.html">迁移</a></td><td>明确新增代码/迁移/权限/测试的范围，不重写已执行checksum</td></tr><tr><td>6</td><td><a href="./../contributing/contribution.html">贡献流程</a>、<a href="./../contributing/gitflow.html">双仓协作</a></td><td>准备可审查的源码配对和验证记录</td></tr></tbody></table><p>正常结果是可以沿一条真实模块链解释“按钮为什么可用、服务如何校验、失败怎么恢复”。源码片段是学习范式，不代表自动生成的完整SDK，也不假设已接入两个真实业务系统。</p><h2 id="运维与交付-安装、升级、恢复分别核验" tabindex="-1">运维与交付：安装、升级、恢复分别核验 <a class="header-anchor" href="#运维与交付-安装、升级、恢复分别核验" aria-label="Permalink to &quot;运维与交付：安装、升级、恢复分别核验&quot;">​</a></h2><p>先读<a href="./../guide/environment.html">环境</a>、<a href="./../operations/deployment.html">部署</a>和<a href="./../operations/security.html">安全配置</a>，再读<a href="./../operations/backup-restore.html">备份恢复</a>与<a href="./../releases/upgrade.html">升级</a>。用<a href="./../releases/versions.html">候选版本</a>识别代码配对，按<a href="./../operations/quality-gates.html">质量门禁</a>区分本地报告与远端CI。</p><p>真实部署的正常结果是有可访问的管理应用、同源 API、独立静态文档、受保护的凭据和经过恢复核验的备份。默认文档路径 <code>/docs/</code>；项目 Pages 使用 <code>/xinghui-admin-vue3/docs/</code>，完整步骤见<a href="./../operations/deployment.html">部署</a>。静态站点发布成功不能替代后端安装和恢复核验。</p><h2 id="搜索与失败恢复" tabindex="-1">搜索与失败恢复 <a class="header-anchor" href="#搜索与失败恢复" aria-label="Permalink to &quot;搜索与失败恢复&quot;">​</a></h2><p>搜索“字典管理”查功能页，搜索 <code>CONFIG_MASTER_KEY</code> 查加密配置及恢复说明；使用本页目录在章节内定位。没有结果时按侧栏分类阅读，或确认文档产物是否落后于应用源码。</p><p>应用的帮助链接按当前路由映射到已定义章节，不把路由 query、手机号或登录令牌拼到地址里。若帮助页404，先检查 <code>/docs/</code> 静态挂载、章节 <code>.html</code> 文件和部署版本。不能靠清空登录、权限或语言存储来修正文档部署。未知功能会回到通用阅读说明，不生成未经验证的新文档地址。</p><h2 id="实际源码来源" tabindex="-1">实际源码来源 <a class="header-anchor" href="#实际源码来源" aria-label="Permalink to &quot;实际源码来源&quot;">​</a></h2><ul><li>前端 <code>apps/docs/.vitepress/chapters.mjs</code>：分类与应用路由帮助映射。</li><li>前端 <code>apps/web-ele/src/layouts/documentation.ts</code>、<code>basic.vue</code>：安全文档地址、当前帮助、版本入口。</li><li>前端 <code>apps/web-ele/src/router/routes-helper.ts</code>：个人入口和动态业务菜单分开。</li><li>前端 <code>apps/web-ele/src/views/_core/about/index.vue</code>：项目候选版本与上游版本分开说明。</li></ul>',22)])])}const f=a(i,[["render",h]]);export{m as __pageData,f as default};
